/* =========================================================================
   form-doc.js — 香港物業 表格3「出售香港住宅物業用的地產代理協議」
   全份條文按紙本一字不漏轉錄；new-listing.html 同 sign.html 共用。
   ========================================================================= */
window.HKREA = (function () {

  const LOGO = "data:image/png;base64,";

  const AGENT_NAME   = "香港物業（銅鑼灣分行）";
  const AGENT_LIC    = "C-009244";
  const AGENT_ADDR   = "香港銅鑼灣告士打道266號海宮大廈地下3號舖";
  const AGENT_TEL    = "2833 1980";
  const AGENT_FAX    = "2833 2016";

  /* ---------- 小工具 ---------- */
  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"]/g, c =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  }

  // 填寫欄：有值就顯示，冇值就留空白線
  function f(v, w) {
    const width = w || 90;
    if (v === 0 || (v && String(v).trim() !== "")) {
      return `<span class="fill" style="min-width:${width}px">${esc(v)}</span>`;
    }
    return `<span class="fill blank" style="min-width:${width}px">&nbsp;</span>`;
  }

  // 方格 ☐ / ☑
  function cb(on) { return `<span class="cb${on ? " on" : ""}"></span>`; }

  // 刪去不適用者（註釋1）
  function opt(text, chosen, any) {
    if (!any) return `<span class="opt">${esc(text)}</span>`;
    return `<span class="opt${chosen ? " pick" : " del"}">${esc(text)}</span>`;
  }

  function sup(n) { return `<sup>(${n})</sup>`; }

  // 統一流水號格式：No.2026-0004（如已經係呢個格式就照用）
  function formatSerial(raw) {
    if (!raw) return "";
    const s = String(raw).trim();
    // 已經係 No.2026-0007 格式，直接用
    if (/^No\.\d{4}-\d+$/i.test(s)) return s.replace(/^no\./i, "No.");
    // 資料庫嗰欄已經係 2026-0007 咁樣（年份-序號），只需要加返個「No.」，唔可以再攞晒啲數字去砌一次
    const ym = s.match(/^(\d{4})-(\d+)$/);
    if (ym) return `No.${ym[1]}-${ym[2].padStart(4, "0")}`;
    // 淨係得個純數字（例如 7），先用今年做年份自己砌
    const n = parseInt(s.replace(/[^\d]/g, ""), 10);
    const y = new Date().getFullYear();
    if (!isNaN(n) && n > 0 && /^\d+$/.test(s)) return `No.${y}-${String(n).padStart(4, "0")}`;
    return s.startsWith("No.") ? s : `No.${s}`;
  }

  // 賣方姓名：支援多於一位賣方（sellers 陣列），冇就退返用單一 seller_name
  function sellerNames(d) {
    if (Array.isArray(d.sellers) && d.sellers.length) {
      return d.sellers.filter(x => x && String(x).trim()).join("、");
    }
    return d.seller_name || "";
  }

  // 留空又想劃線（表示「不適用」）嗰啲位用呢個：勾咗 na 就畫斜線，冇勾就係普通留白
  function naLine(naFlag) {
    return `<div class="lineblank${naFlag ? " na" : ""}"></div>`;
  }
  function naFill(v, w, naFlag) {
    if (naFlag) return `<span class="fill na" style="min-width:${w || 90}px">&nbsp;</span>`;
    return f(v, w);
  }
  // 同 naFill 一樣，但用喺句子中間唔想開新一行嘅位（例如「將佣金 X/Y 退還」）
  function naInline(w) {
    return `<span class="fill na" style="min-width:${w || 70}px">&nbsp;</span>`;
  }

  // 日期拆做 年 / 月 / 日
  function dparts(iso) {
    if (!iso) return { y: "", m: "", d: "" };
    const p = String(iso).split("-");
    return { y: p[0] || "", m: p[1] ? String(+p[1]) : "", d: p[2] ? String(+p[2]) : "" };
  }
  function dline(iso) {
    const p = dparts(iso);
    return `${f(p.y, 52)} 年 ${f(p.m, 32)} 月 ${f(p.d, 32)} 日`;
  }
  function dateCN(iso) {
    const p = dparts(iso);
    return p.y ? `${p.y} 年 ${p.m} 月 ${p.d} 日` : "";
  }

  // 銀碼轉中文大寫（放盤價用）
  function num2cn(n, withUnit) {
    n = parseInt(String(n).replace(/[^\d]/g, ""), 10);
    if (!n || isNaN(n)) return "";
    const D = "零壹貳參肆伍陸柒捌玖".split("");
    const U = ["", "拾", "佰", "仟"];
    const G = ["", "萬", "億", "兆"];
    let s = String(n), out = "", g = 0;
    while (s.length) {
      const chunk = s.slice(-4); s = s.slice(0, -4);
      let part = "", zero = false;
      for (let i = 0; i < chunk.length; i++) {
        const d = +chunk[i], u = chunk.length - i - 1;
        if (d === 0) { zero = true; }
        else {
          if (zero && part) part += D[0];
          zero = false;
          part += D[d] + U[u];
        }
      }
      if (part) out = part + G[g] + out;
      else if (out && !/^零/.test(out)) out = D[0] + out;
      g++;
    }
    return out;
  }

  /* ---------- 樣式（兩個頁面共用） ---------- */
  const CSS = `
  .paper, .paper *{ box-sizing:border-box; }
  .paper{
    --doc-ink:#1a3a8c;
    width:793px; min-height:1122px; background:#fff; color:#111;
    padding:10mm 12mm 12mm; margin:0 auto; position:relative;
    font-family:"PingFang HK","Noto Sans HK","Microsoft JhengHei","MingLiU",serif;
    font-size:10.5px; line-height:1.52; letter-spacing:.1px;
    box-shadow:0 2px 18px rgba(0,0,0,.14);
  }
  .paper + .paper{ margin-top:18px; }
  .paper sup{ font-size:.66em; vertical-align:super; line-height:0; }
  .paper .hd{ display:grid; grid-template-columns:318px 1fr auto; align-items:center; gap:12px; margin-bottom:4px; }
  .paper .hd .lh img{ width:318px; height:auto; display:block; }
  .paper .hd .mid{ text-align:center; font-size:13.5px; font-weight:700; letter-spacing:.3px; }
  .paper .hd .rt{ text-align:right; display:flex; flex-direction:column; align-items:flex-end; }
  .paper .formtag{
    display:inline-block; border:1px solid #333; border-radius:3px;
    padding:1px 9px; font-size:11px; font-weight:700;
  }
  .paper .serialno{
    margin-top:6px; font-size:13px; font-weight:700; color:#c1121f;
    letter-spacing:.5px; white-space:nowrap;
  }
  .paper .serialno em{ font-style:normal; font-size:11px; color:#444; margin-right:3px; }
  .paper .note-lead{ margin:7px 0 3px; display:flex; gap:6px; }
  .paper .note-lead .k{ flex:0 0 auto; text-decoration:underline; white-space:nowrap; }
  .paper .clause{ display:flex; gap:5px; margin-top:4px; }
  .paper .clause > .n{ flex:0 0 17px; }
  .paper .clause > .c{ flex:1 1 auto; }
  .paper .sub{ margin-left:14px; }
  .paper .row{ display:flex; justify-content:space-between; align-items:flex-end; gap:10px; }
  .paper .row .q{ flex:1 1 auto; }
  .paper .row .a{ flex:0 0 auto; white-space:nowrap; }
  .paper .warn{ margin-top:3px; }
  .paper .fill{
    display:inline-block; border-bottom:1px solid #444; padding:0 4px;
    color:var(--doc-ink); font-weight:700; text-align:center; line-height:1.35;
    word-break:break-word;
  }
  .paper .fill.blank{ color:transparent; font-weight:400; }
  .paper .fill.wide{ display:block; width:100%; min-height:15px; }
  .paper .cb{
    display:inline-block; width:12px; height:12px; border:1px solid #333;
    vertical-align:-2px; margin:0 3px; position:relative; background:#fff;
  }
  .paper .cb.on::after{
    content:"✓"; position:absolute; left:0; top:0; width:12px; height:12px;
    display:flex; align-items:center; justify-content:center;
    font-size:11px; font-weight:700; color:var(--doc-ink); line-height:1;
  }
  .paper .opt.del{ text-decoration:line-through; color:#999; }
  .paper .opt.pick{ font-weight:700; color:var(--doc-ink); }
  .paper .lineblank{ border-bottom:1px solid #444; height:15px; margin:7px 0; position:relative; }
  .paper .lineblank.na{ border-bottom-color:#999; }
  .paper .lineblank.na::after{
    content:""; position:absolute; left:0; right:0; top:50%; border-top:1px solid #444;
  }
  .paper .fill.na{ text-decoration:line-through; color:#999 !important; }
  .paper .sched-h{ text-align:center; font-weight:700; margin:14px 0 4px; font-size:11.6px; }
  .paper .sigwrap{ display:flex; gap:26px; margin-top:4px; }
  .paper .sigcol{ flex:1 1 0; min-width:0; }
  .paper .sigrow{ display:flex; align-items:flex-end; gap:4px; margin-bottom:9px; }
  .paper .sigrow .lb{ flex:0 0 auto; white-space:nowrap; }
  .paper .sigrow .vl{ flex:1 1 auto; border-bottom:1px solid #444; min-height:15px;
    text-align:center; color:var(--doc-ink); font-weight:700; padding:0 4px; }
  .paper .sigrow .vl img{ max-height:42px; max-width:100%; display:block; margin:0 auto; }
  .paper .fixed{ color:#111; font-weight:600; }
  .paper .foot-note{ margin-top:8px; }
  .paper .pageno{
    position:absolute; left:0; right:0; bottom:5mm; text-align:center;
    font-size:9.5px; color:#666; letter-spacing:.5px;
  }
  .paper .pageno .r{ position:absolute; right:12mm; bottom:0; }
  .paper .hd-mini{
    display:flex; align-items:center; gap:8px; padding-bottom:6px; margin-bottom:12px;
    border-bottom:1px solid #ccc; font-size:9px; color:#777; letter-spacing:.2px;
  }
  .paper .hd-mini img{ height:20px; width:auto; display:block; }
  .paper .hd-mini .t{ flex:1; }
  .paper .hd-mini .n{ font-weight:700; color:#666; }
  @media print{
    @page{ size:A4 portrait; margin:0; }
    .paper{ box-shadow:none; margin:0 auto; page-break-after:always; break-after:page; }
    .paper:last-child{ page-break-after:auto; break-after:auto; }
  }
  `;

  /* ---------- 第一頁：條款 1–13 ---------- */
  function page1(d) {
    const ex = d.agency_type === "獨家", nonex = d.agency_type === "非獨家";
    const anyAg = ex || nonex;
    const rel = d.rel_type;
    const anyRel = !!rel;

    return `
    <div class="paper">
      <div class="hd">
        <div class="lh"><img src="${LOGO}" alt=""></div>
        <div class="mid">出售香港住宅物業用的地產代理協議</div>
        <div class="rt">
          <div class="formtag">表格 3</div>
          <div class="serialno">${esc(formatSerial(d.serial_no) || "No.—")}</div>
        </div>
      </div>

      <div class="note-lead">
        <div class="k">一般注意事項 ：</div>
        <div>請仔細閱讀本協議並按指示填寫。如你不明白本協議內的任何字句，請要求代理解釋。如你不明白或不同意代理的解釋，則最佳的做法是在簽署本協議前諮詢你的律師。</div>
      </div>
      <div class="note-lead">
        <div class="k">備　　註 ：</div>
        <div>凡本協議內的任何字句尾隨有括號的數字（例如<sup>(1)</sup>），請立即參閱本協議附表4內相同編號的註釋。<br>
        凡本協議內的任何字句提述本協議的某附表，亦請立即參閱該附表。</div>
      </div>

      <div class="clause"><div class="n">1.</div><div class="c">
        <b>代理的委任及本協議的有效期：</b>
        <div class="sub">
          本人/我們：${f(sellerNames(d), 300)}（“賣方”）現按照本協議的條款並在該等條款的規限下
          委任 ${f(AGENT_NAME, 190)}（“代理${sup(2)}”）為本人/我們的
          ${opt("獨家", ex, anyAg)}${sup(3)}/${opt("非獨家", nonex, anyAg)}${sup(1)}代理，以推銷位於
          ${f(d.property_address, 320)} 的物業（“物業”）。
          <div style="margin-top:4px;">本協議由 ${dline(d.effective_from)} 起生效，並於 ${dline(d.effective_to)} 屆滿（首尾兩天包括在內）（“有效期”）。</div>
          <div class="warn">【注意：如屬獨家代理關係，則即使物業在有效期內並非經由代理出售，賣方仍可能須向代理支付佣金，因此當賣方與代理建立獨家代理關係時應謹慎考慮。代理以獨家代理身分行事時須履行的特別責任，可在第13條下以額外條款的形式指明。】</div>
        </div>
      </div></div>

      <div class="clause"><div class="n">2.</div><div class="c">
        <b>代理關係及代理的責任：</b> 代理與賣方同意 —
        <div class="sub">(a) 代理與賣方之間就物業而有的代理關係屬
          ${opt("單邊代理", rel === "單邊代理", anyRel)}/${opt("雙邊代理", rel === "雙邊代理", anyRel)}/${opt("有可能代表雙方的代理", rel === "有可能代表雙方的代理", anyRel)}${sup(3)}${sup(1)}關係；</div>
        <div class="sub">(b) 如屬雙邊代理關係，則代理須在切實可行的範圍內，盡快以書面向賣方披露代理將向買方收取的佣金的數額或收費率；</div>
        <div class="sub">(c) 如屬有可能代表雙方的代理關係，則代理須在建立雙邊代理關係後，在切實可行的範圍內，盡快以書面向賣方披露該代理關係以及代理將向買方收取的佣金的數額或收費率；及</div>
        <div class="sub">(d) 代理除須履行本協議或任何成文法則委予代理的責任外，亦須履行本協議附表1內所列的責任。</div>
      </div></div>

      <div class="clause"><div class="n">3.</div><div class="c">
        <b>放盤價</b>【注意：賣方並沒有藉本條授權代理代賣方接受任何要約。放盤價只供放盤及作廣告宣傳之用。】：
        <div class="sub" style="margin-top:3px;">放盤價為港幣 ${f(num2cn(d.asking_price), 250)} 元（HK$ ${f(d.asking_price ? Number(d.asking_price).toLocaleString("en-US") : "", 150)}）。</div>
        <div class="sub">放盤價只在賣方的書面指示下方可更改，而該等指示將構成本協議一部分。</div>
      </div></div>

      <div class="clause"><div class="n">4.</div><div class="c">
        <b>佣金：</b> 本協議適用於賣方須向代理支付的佣金的規定，列於本協議附表2及4內${sup(4)}。
      </div></div>

      <div class="clause"><div class="n">5.</div><div class="c">
        <b>物業資料：</b>代理須向賣方提供《地產代理常規（一般責任及香港住宅物業）規例》訂明並經代理填妥和簽署的物業資料表格（包括賣方的陳述）。
      </div></div>

      <div class="clause"><div class="n">6.</div><div class="c">
        <b>視察物業：</b>
        <div class="sub row"><div class="q">(a) 賣方同意容許代理/買方${sup(1)}於雙方議定的時間查看物業。</div>
          <div class="a">同意${cb(d.q_viewing === "同意")} 不同意${cb(d.q_viewing === "不同意")}${sup(8)}</div></div>
        <div class="sub row"><div class="q">(b) 賣方同意將物業的鎖匙交由代理妥為保管，以供查看物業之用。</div>
          <div class="a">同意${cb(d.q_key === "同意")} 不同意${cb(d.q_key === "不同意")}${sup(8)}</div></div>
        <div class="sub row"><div class="q">(c) 賣方授權代理將鎖匙交予其他地產代理/人士${sup(1)}，以供查看物業之用。</div>
          <div class="a">同意${cb(d.q_key_other === "同意")} 不同意${cb(d.q_key_other === "不同意")}${sup(8)}</div></div>
      </div></div>

      <div class="clause"><div class="n">7.</div><div class="c">
        <b>分銷放盤：</b>
        <div class="sub">(a) 賣方授權代理將物業分銷放盤，並將由賣方提供的關於賣方及物業的資料交予其他地產代理以供分銷放盤之用。
          <div style="margin-left:14px;">同意${cb(d.q_distribute === "同意")} 不同意${cb(d.q_distribute === "不同意")}${sup(8)}</div></div>
        <div class="sub">(b) 如代理將物業交由另一地產代理（“分銷放盤代理”）分銷放盤，則代理須確保分銷放盤代理遵守《地產代理常規（一般責任及香港住宅物業）規例》中關於廣告宣傳的規定。</div>
      </div></div>

      <div class="clause"><div class="n">8.</div><div class="c">
        <b>廣告宣傳：</b>
        <div class="sub row"><div class="q">(a) 賣方授權代理發出關於物業的廣告。</div>
          <div class="a">同意${cb(d.q_advertise === "同意")} 不同意${cb(d.q_advertise === "不同意")}${sup(8)}</div></div>
        <div class="sub">(b) 如對以上問題的回答是“同意”的話，則除本協議另有指明外，廣告宣傳費將由代理承擔。</div>
      </div></div>

      <div class="clause"><div class="n">9.</div><div class="c">
        <b>代理須披露權益：</b>
        <div class="sub row"><div class="q">(a) 代表代理簽署本協議的人現披露：他或其指明親屬${sup(5)}，或其任何代名人，或其指明親屬的任何代名人，或代理或代理的任何僱員/大股東${sup(6)}/合夥人/董事對物業擁有金錢上的或其他實益的權益${sup(7)}：</div>
          <div class="a">有${cb(d.q_interest === "有")} 沒有${cb(d.q_interest === "沒有")}${sup(8)}</div></div>
        <div class="sub">(b) 如對以上問題的回答是“有”的話，則必須在本協議附表3述明有關權益的詳情。</div>
        <div class="sub">(c) 代表代理簽署本協議的人須在切實可行的範圍內，盡快以書面向賣方披露在有效期內產生的上述(a)段所提述的任何權益。</div>
      </div></div>

      <div class="clause"><div class="n">10.</div><div class="c">
        <b>賣方的確認：</b> 賣方確認他已 —
        <div class="sub">(a) 閱讀並明白本協議的條款；及</div>
        <div class="sub">(b) ${cb(d.ack_option === "已收取")}${sup(8)} 收取本協議第5條規定提供的物業資料表格（包括賣方的陳述）。</div>
        <div class="sub" style="margin-left:30px;">${cb(d.ack_option === "簽約前收取")}${sup(8)} 同意於賣方與一名買方訂立具約束力的買賣協議之前收取物業資料表格（包括賣方的陳述）。</div>
      </div></div>

      <div class="clause"><div class="n">11.</div><div class="c">
        <b>附表：</b> 本協議的附表構成本協議的一部分。
      </div></div>

      <div class="clause"><div class="n">12.</div><div class="c">
        <b>如物業不容許作住宅用途則本協議即屬無效：</b>
        <div class="sub">如物業的佔用許可證所規定的用途並不包括住宅用途或不容許作住宅用途，則本協議即屬無效。</div>
      </div></div>

      <div class="clause"><div class="n">13.</div><div class="c">
        <b>額外條款</b>【注意：這些額外條款不得與本協議的其他條款有所抵觸，亦不得限制本協議的其他條款。】：
        <div class="sub" style="margin-top:6px;">
          ${d.extra_terms
            ? `<span class="fill wide" style="text-align:left;">${esc(d.extra_terms).replace(/\n/g, "<br>")}</span>`
            : `${naLine(d.extra_terms_na)}${naLine(d.extra_terms_na)}`}
        </div>
      </div></div>
      <div class="pageno">第 1 頁 ‧ 共 2 頁<span class="r">${esc(formatSerial(d.serial_no))}</span></div>
    </div>`;
  }

  /* ---------- 第二頁：簽署欄 + 附表 1–4 ---------- */
  function page2(d) {
    const sig = d.signature_img ? `<img src="${d.signature_img}" alt="賣方簽署">` : "&nbsp;";
    const asig = d.agent_signature ? `<img src="${d.agent_signature}" alt="代理簽署">` : "&nbsp;";

    return `
    <div class="paper">
      <div class="hd-mini">
        <img src="${LOGO}" alt="">
        <span class="t">出售香港住宅物業用的地產代理協議（表格 3）</span>
        <span class="n">${esc(formatSerial(d.serial_no))}</span>
      </div>
      <div class="sigwrap">
        <div class="sigcol">
          <div class="sigrow" style="align-items:flex-end;">
            <div class="lb">賣方的簽署：</div><div class="vl">${sig}</div></div>
          <div class="sigrow"><div class="lb">香港身份證號碼（如適用的話）：</div><div class="vl">${esc(d.seller_id || "")}</div></div>
          <div class="sigrow"><div class="lb">如賣方是一間公司，請述明：</div><div class="vl">${esc(d.seller_company || "")}</div></div>
          <div class="sigrow"><div class="lb">簽署人的姓名或名稱：</div><div class="vl">${esc(d.signer_name || "")}</div></div>
          <div class="sigrow"><div class="lb">簽署人的職位：</div><div class="vl">${esc(d.signer_title || "")}</div></div>
          <div class="sigrow"><div class="lb">賣方的商業登記證號碼：</div><div class="vl">${esc(d.seller_br || "")}</div></div>
          <div class="sigrow"><div class="lb">地　　址：</div><div class="vl">${esc(d.seller_address || "")}</div></div>
          <div class="sigrow"><div class="lb">電話號碼：</div><div class="vl">${esc(d.seller_phone || "")}</div></div>
          <div class="sigrow"><div class="lb">傳真號碼：</div><div class="vl">${esc(d.seller_fax || "")}</div></div>
          <div class="sigrow"><div class="lb">日　　期：</div><div class="vl">${esc(dateCN(d.seller_date))}</div></div>
        </div>
        <div class="sigcol">
          <div style="margin-bottom:9px;">為代理及代代理簽署的</div>
          <div class="sigrow"><div class="lb">地產代理/營業員的簽署：</div><div class="vl">${asig}</div></div>
          <div class="sigrow"><div class="lb">簽署人的姓名或名稱及牌照號碼：</div><div class="vl">${esc(d.agent_signer || "")}</div></div>
          <div class="sigrow" style="margin-top:22px;"><div class="lb">代理的營業詳情說明書號碼：</div><div class="vl fixed">${AGENT_LIC}</div></div>
          <div class="sigrow"><div class="lb">地　　址：</div><div class="vl fixed" style="font-size:10px;">${AGENT_ADDR}</div></div>
          <div class="sigrow"><div class="lb">電話號碼：</div><div class="vl fixed">${AGENT_TEL}</div></div>
          <div class="sigrow"><div class="lb">傳真號碼：</div><div class="vl fixed">${AGENT_FAX}</div></div>
          <div class="sigrow"><div class="lb">日　　期：</div><div class="vl">${esc(dateCN(d.agent_date))}</div></div>
        </div>
      </div>
      <div class="foot-note">【注意：在本協議簽署後，必須立即給予賣方一份經簽署的本協議的正本或副本。】</div>

      <div class="sched-h">附表 1 － 代理的責任</div>
      <div style="display:flex; gap:10px;">
        <div style="flex:0 0 auto;">代理須 －</div>
        <div style="flex:1 1 0;">
          (a) 代賣方推銷物業；<br>
          (c) 安排買方視察物業<br>
          (e) 協助賣方與買方訂立具約束力的買賣協議。
        </div>
        <div style="flex:1 1 0;">
          (b) 為賣方取得關於物業的資料；<br>
          (d) 進行商議，並向賣方提交所有關於物業的要約；及
        </div>
      </div>

      <div class="sched-h">附表 2 － 賣方須支付的佣金</div>
      <div class="clause"><div class="n">1.</div><div class="c">
        除本附表第2條另有規定外，如賣方在有效期內經由代理與買方就物業訂立具約束力的買賣協議，則賣方須於：
        <div class="sub" style="margin-top:2px;">
          ${cb(d.commission_timing === "簽署買賣協議時")}${sup(8)} 簽署買賣協議時，
          <span style="display:inline-block; width:46px;"></span>
          ${cb(d.commission_timing === "物業交易完成時")}${sup(8)} 買賣協議指明的物業交易完成時，
        </div>
        <div class="sub" style="margin-top:3px;">
          向代理支付一筆數額$ ${naFill(d.commission_amount, 200, d.commission_amount_na)} /物業成交價的 ${naFill(d.commission_pct, 90, d.commission_pct_na)} %${sup(1)}作為代理的佣金。
        </div>
      </div></div>
      <div class="clause"><div class="n">2.</div><div class="c">
        除本附表第3條另有規定外，如非因賣方犯錯而令物業交易未能完成，則賣方沒有責任向代理支付任何佣金。在此情況下，如賣方已支付佣金，則代理須在切實可行的範圍內盡快（但無論如何不得遲於由買賣協議指明的完成交易日期起計的5個工作日）將佣金${
          d.commission_interest_na
            ? `${naInline()}/${naInline()}`
            : `${opt("連同利息", d.commission_interest === "連同利息", !!d.commission_interest)}/${opt("不連同利息", d.commission_interest === "不連同利息", !!d.commission_interest)}`
        }${sup(1)}退還予賣方。
      </div></div>
      <div class="clause"><div class="n">3.</div><div class="c">
        如買賣雙方非基於物業的買賣協議的條文而共同取消該具約束力的買賣協議，則賣方須向代理支付佣金。
      </div></div>
      <div class="clause"><div class="n">4.</div><div class="c">
        如代理為推銷物業而與其他地產代理合作，則賣方無須向該等其他地產代理支付任何佣金。
      </div></div>

      <div class="sched-h">附表3 － 對物業所擁有的權益</div>
      <div>按照本協議第9條，就物業所擁有的金錢上的或其他實益的權益${sup(7)}的詳情如下：</div>
      ${d.interest_details
        ? `<div class="fill wide" style="text-align:left; margin-top:6px;">${esc(d.interest_details).replace(/\n/g, "<br>")}</div>`
        : `${naLine(d.interest_details_na)}${naLine(d.interest_details_na)}`}

      <div class="sched-h">附表4 － 註釋</div>
      <div>(1) 指刪去不適用者。所有刪除必須加以簡簽。</div>
      <div>(2) 在本協議第1條內填上有關地產代理業務實體（即俗稱商號）的名稱。</div>
      <div>(3) 獨家代理－指代理是唯一為賣方行事的地產代理。如賣方在有效期內經由另一地產代理與一名買方就物業訂立具約束力的買賣協議，則代理有權向賣方追討附表2第1條所指明的佣金。</div>
      <div class="sub">單邊代理－指代理只為賣方行事。</div>
      <div class="sub">雙邊代理－指代理既為賣方亦為物業的買方行事。</div>
      <div class="sub">有可能代表雙方的代理－指代理只為賣方行事，但於稍後亦可能為物業的買方行事。</div>
      <div>(4) 佣金的數額或收費率可由賣方與代理商議。</div>
      <div>(5) 指明親屬－指配偶、父母、子女、兄弟或姊妹。</div>
      <div>(6) 大股東－指在代理的股東大會上，有權行使百分之十或以上的投票權或控制百分之十或以上的投票權的行使的人。</div>
      <div>(7) 擁有金錢上的或其他實益的權益，包括：</div>
      <div class="sub">(a) 身為對物業擁有金錢上的或其他實益的權益的公司或任何其他團體的成員；</div>
      <div class="sub">(b) 與對物業擁有金錢上的或其他實益的權益的人有合夥關係，或受僱於該人；或</div>
      <div class="sub">(c) 屬於任何關乎物業的安排或協議（不論是否可強制執行）的一方。</div>
      <div>(8) 請於適當的方格內劃上“<span class="cb on" style="vertical-align:-2px;"></span>”號。</div>
      <div class="pageno">第 2 頁 ‧ 共 2 頁<span class="r">${esc(formatSerial(d.serial_no))}</span></div>
    </div>`;
  }

  function render(d) { d = d || {}; return page1(d) + page2(d); }

  /* ---------- 員工（營業員）資料：一律存喺 Supabase `staff` 表（全公司共用），唔會存落呢部機 ---------- */
  const staff = {
    async list(sb){
      const { data, error } = await sb.from('staff').select('*').order('name');
      if (error) return { rows: [], remote: false, err: error.message };
      return { rows: data || [], remote: true };
    },
    async save(sb, row){
      const payload = {
        name: row.name || null, licence_no: row.licence_no || null,
        phone: row.phone || null, signature: row.signature || null
      };
      let res;
      if (row.id) res = await sb.from('staff').update(payload).eq('id', row.id).select().single();
      else        res = await sb.from('staff').insert(payload).select().single();
      if (res.error) return { row: null, remote: false, err: res.error.message };
      return { row: res.data, remote: true };
    },
    async remove(sb, id){
      const { error } = await sb.from('staff').delete().eq('id', id);
      if (error) return { remote: false, err: error.message };
      return { remote: true };
    },
    label(r){ return (r.name || '') + (r.licence_no ? ' ' + r.licence_no : ''); }
  };

  return {
    render, css: CSS, staff, formatSerial, sellerNames,
    num2cn: (n,u) => { const v = num2cn(n); return v && u ? v + '元整' : v; },
    AGENT_NAME, AGENT_LIC, AGENT_ADDR, AGENT_TEL, AGENT_FAX
  };
})();
